import React, { useState } from 'react';
import './FindProfessionalsPage.css';

const FindProfessionalsPage = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('all');

  const professionals = [
    {
      id: 1,
      name: "Sarah Johnson",
      category: "Interior Designer",
      rating: 4.9,
      reviews: 127,
      location: "San Francisco, CA",
      phone: "(415) 555-0123",
      email: "sarah@johnsondesign.com",
      specialties: ["Modern Design", "Kitchen Remodeling", "Space Planning"],
      experience: 8,
      image: "https://images.unsplash.com/photo-1494790108755-2616b612b8e5?w=150&h=150&fit=crop&crop=face"
    },
    {
      id: 2,
      name: "Michael Chen",
      category: "Architect",
      rating: 4.8,
      reviews: 89,
      location: "New York, NY",
      phone: "(212) 555-0456",
      email: "mike@chenarchitects.com",
      specialties: ["Residential Architecture", "Sustainable Design", "Renovations"],
      experience: 12,
      image: "https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=150&h=150&fit=crop&crop=face"
    },
    {
      id: 3,
      name: "Emily Rodriguez",
      category: "Contractor",
      rating: 4.7,
      reviews: 156,
      location: "Los Angeles, CA",
      phone: "(323) 555-0789",
      email: "emily@rodriguezcontracting.com",
      specialties: ["Home Renovations", "Bathroom Remodeling", "Custom Carpentry"],
      experience: 10,
      image: "https://images.unsplash.com/photo-1580489944761-15a19d654956?w=150&h=150&fit=crop&crop=face"
    }
  ];

  const categories = ['all', 'Interior Designer', 'Architect', 'Contractor', 'Landscaper'];

  const filteredProfessionals = professionals.filter(pro => {
    const matchesSearch = pro.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         pro.specialties.some(spec => spec.toLowerCase().includes(searchTerm.toLowerCase()));
    const matchesCategory = selectedCategory === 'all' || pro.category === selectedCategory;
    return matchesSearch && matchesCategory;
  });

  return (
    <div className="professionals-page">
      <div className="container">
        <h1 className="page-title">Find Professionals</h1>
        <p className="page-subtitle">Connect with top-rated home professionals in your area</p>
        
        <div className="search-filters">
          <div className="search-container">
            <input
              type="text"
              placeholder="Search professionals or specialties..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="search-input"
            />
          </div>
          
          <div className="category-filters">
            {categories.map(category => (
              <button
                key={category}
                className={`filter-btn ${selectedCategory === category ? 'active' : ''}`}
                onClick={() => setSelectedCategory(category)}
              >
                {category === 'all' ? 'All Categories' : category}
              </button>
            ))}
          </div>
        </div>
        
        <div className="professionals-grid">
          {filteredProfessionals.map(pro => (
            <div key={pro.id} className="professional-card">
              <div className="pro-header">
                <img src={pro.image} alt={pro.name} className="pro-image" />
                <div className="pro-basic-info">
                  <h3 className="pro-name">{pro.name}</h3>
                  <p className="pro-category">{pro.category}</p>
                  <div className="pro-rating">
                    <span className="stars">⭐ {pro.rating}</span>
                    <span className="reviews">({pro.reviews} reviews)</span>
                  </div>
                </div>
              </div>
              
              <div className="pro-details">
                <p className="pro-location">📍 {pro.location}</p>
                <p className="pro-experience">🏆 {pro.experience} years experience</p>
                
                <div className="pro-specialties">
                  <h4>Specialties:</h4>
                  <div className="specialty-tags">
                    {pro.specialties.map((specialty, index) => (
                      <span key={index} className="specialty-tag">{specialty}</span>
                    ))}
                  </div>
                </div>
                
                <div className="pro-contact">
                  <p>📞 {pro.phone}</p>
                  <p>✉️ {pro.email}</p>
                </div>
                
                <div className="pro-actions">
                  <button className="contact-btn">Send Message</button>
                  <button className="portfolio-btn">View Portfolio</button>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default FindProfessionalsPage;
